import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Blockly-Abgleich, Farben und Funktionen","description":"Abgleich aller Standardkategorien mit ioBroker und eigener Home-Assistant-Ausgabe.","frontmatter":{"title":"Blockly-Abgleich, Farben und Funktionen","description":"Abgleich aller Standardkategorien mit ioBroker und eigener Home-Assistant-Ausgabe."},"headers":[],"relativePath":"projects/blocks-for-ha/blockly-audit.md","filePath":"projects/blocks-for-ha/blockly-audit.md","lastUpdated":1793128957000}'),a={name:"projects/blocks-for-ha/blockly-audit.md"};function o(d,e,l,s,c,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="blockly-abgleich-farben-und-funktionen" tabindex="-1">Blockly-Abgleich, Farben und Funktionen <a class="header-anchor" href="#blockly-abgleich-farben-und-funktionen" aria-label="Permalink to &quot;Blockly-Abgleich, Farben und Funktionen&quot;">​</a></h1><h2 id="aktionsfunktionen-und-bedingte-ruckgaben-seit-0-1-47" tabindex="-1">Aktionsfunktionen und bedingte Rückgaben seit 0.1.47 <a class="header-anchor" href="#aktionsfunktionen-und-bedingte-ruckgaben-seit-0-1-47" aria-label="Permalink to &quot;Aktionsfunktionen und bedingte Rückgaben seit 0.1.47&quot;">​</a></h2><p>Unter <strong>Funktionen</strong> kann eine Aktionsfunktion neben der Automation definiert werden. Einen gültigen Namen ohne Leerzeichen eingeben, über das Zahnrad bis zu acht unterschiedliche ASCII-Parameter hinzufügen und HA-Aktionen in den Körper einsetzen. Der passende Aufruf erscheint automatisch in derselben Kategorie; alle Argumente müssen angeschlossen werden. Parameter mit Variablenblöcken aus <strong>Variablen</strong> lesen, beispielsweise als Log-Nachricht, Pause oder Wert einer Variablenzuweisung.</p><p>Beim Export entsteht eine native HA-<code>sequence</code>. Jeder Aufruf erhält eigene interne Parameterbindungen; Argumente werden beim Aufruf ausgewertet. Verschachtelte Aufrufe bleiben möglich, Rekursion und leere Aktionskörper nicht. Gleichnamige HA-Variablen werden durch die Parameterbindung nicht überschrieben. Andere Variablenzuweisungen im Körper sind normale HA-Zuweisungen. Freie Jinja-/JSON-Textfelder bleiben im normalen HA-Kontext und werden nicht auf lokale Parameter umgeschrieben; dafür Variablenblöcke anschließen. <strong>Stop</strong> beendet weiterhin den gesamten HA-Lauf.</p><p>Der Wertblock <strong>Falls / gib zurück / sonst</strong> liefert den passenden Wert als Jinja-Ausdruck. Nur der ausgewählte Zweig wird ausgewertet; er kann an den Rückgabeeingang einer Wertfunktion oder an andere Werteingänge angeschlossen werden. Beide Wertzweige und die Bedingung sind erforderlich. Er ist kein vorzeitiges <code>return</code> aus einer Aktionsfolge.</p><p>JSON-Projekte bewahren Definitionen, Parameter, Aufrufe und Anordnung. YAML enthält aufgelöste Schritte bzw. Ausdrücke; ein YAML-Reimport rekonstruiert diese Schritte, nicht die ursprünglichen Funktionsdefinitionen. <a href="./blocks#funktionen-seit-0-1-47">Blockbilder</a>. Die folgenden Tabellen dokumentieren zusätzlich den historischen Vergleich von 0.1.15.</p><p>Stand <strong>0.1.15</strong>, 10. Oktober 2026: <strong>111 unterstützte Blocktypen</strong>. Drei Farbberechnungen und drei originale Blockly-Typen für Wertfunktionen/Parameter sind neu. Eine Funktionsdefinition ist neben der Automation erlaubt; andere unverbundene Blocks verhindern weiterhin den Export.</p><h2 id="quellen-und-vorgehen" tabindex="-1">Quellen und Vorgehen <a class="header-anchor" href="#quellen-und-vorgehen" aria-label="Permalink to &quot;Quellen und Vorgehen&quot;">​</a></h2><p>Verglichen wurden die bei uns installierten Standardblocks aus <strong>Blockly 13.3.0</strong>, die originale <a href="https://github.com/raspberrypifoundation/blockly/tree/4195d60c610bec4b4b186aa22d58cb16beb42dfa/blocks" target="_blank" rel="noreferrer">Blockly-Blockbibliothek</a> sowie die <a href="https://github.com/ioBroker/ioBroker.javascript/blob/a87561ce0fd9a4ac05631fb35892fb8cb67613d2/src-editor/index.html" target="_blank" rel="noreferrer">ioBroker-Standardtoolbox</a> und deren <a href="https://github.com/ioBroker/ioBroker.javascript/blob/a87561ce0fd9a4ac05631fb35892fb8cb67613d2/src-editor/src/Components/blockly-plugins/bridge.ts" target="_blank" rel="noreferrer">Blockly-Bridge</a>. Die Links sind auf die geprüften Commits festgelegt.</p><p><strong>Registriert, im Menü angeboten und bei uns exportierbar sind unterschiedliche Dinge.</strong> ioBroker lädt die Standardbibliothek vollständig. Ein dort registrierter Block muss nicht in seiner Standardtoolbox erscheinen. Die Bilder zeigen außerdem nicht zwangsläufig die aktuelle Toolbox. Textumkehr ist inzwischen im ioBroker-Menü enthalten; atan2 fehlt dort, ist aber durch den Bibliotheksimport grundsätzlich registriert. Das ist kein Nachweis, dass ioBroker atan2 nicht ausführen könnte.</p><h2 id="alle-standardkategorien" tabindex="-1">Alle Standardkategorien <a class="header-anchor" href="#alle-standardkategorien" aria-label="Permalink to &quot;Alle Standardkategorien&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kategorie / originale Typen</th><th>ioBroker-Standardmenü</th><th>UGSo / HA und offene Varianten</th></tr></thead><tbody><tr><td>Logik: <code>controls_if</code>, <code>controls_ifelse</code>, <code>logic_compare</code>, <code>logic_operation</code>, <code>logic_negate</code>, <code>logic_boolean</code>, <code>logic_null</code>, <code>logic_ternary</code></td><td>Enthalten; weitere eigene UND/ODER-, Fall-, Bereichs- und Ersatzwertblocks</td><td>Vergleich, Gruppen, Falls/Sonst-wenn/Sonst, Wertauswahl, Bereich und Fallauswahl umgesetzt. Formvarianten werden durch eigene Blocks zusammengefasst.</td></tr><tr><td>Schleifen: <code>controls_repeat</code>, <code>controls_repeat_ext</code>, <code>controls_whileUntil</code>, <code>controls_for</code>, <code>controls_forEach</code></td><td>Enthalten, hauptsächlich Value-Variante der Wiederholungszahl</td><td>Anzahl/solange/bis/für jeden sowie ganzzahlige feste Zählgrenzen umgesetzt. Dynamische oder gebrochene Zählgrenzen offen.</td></tr><tr><td>Schleifensteuerung: <code>controls_flow_statements</code></td><td>break / continue</td><td>Lokales break/continue offen. „Lauf stoppen“ beendet den gesamten HA-Lauf und ist kein Ersatz.</td></tr><tr><td>Mathematik: <code>math_number</code>, <code>math_arithmetic</code>, <code>math_single</code>, <code>math_trig</code>, <code>math_constant</code>, <code>math_number_property</code>, <code>math_round</code>, <code>math_on_list</code>, <code>math_modulo</code>, <code>math_constrain</code>, <code>math_random_int</code>, <code>math_random_float</code>, <code>math_change</code></td><td>Enthalten; zusätzliche feste Nachkommastellen</td><td>Eigene Rechen-, Statistik-, Rundungs-, Zufalls- und Variablenänderungsblocks. Offen: Primzahl, Standardabweichung, Modalwert mit allen Gleichständen und Unendlich. Keine vollständige Gleichheit aller Dropdown-Varianten behauptet.</td></tr><tr><td>Mathematik: <code>math_atan2</code></td><td>Nicht angeboten, Bibliothek registriert</td><td>Vierquadranten-Winkel bereits umgesetzt.</td></tr><tr><td>Text: <code>text</code>, <code>text_join</code>, <code>text_append</code>, <code>text_length</code>, <code>text_isEmpty</code>, <code>text_indexOf</code>, <code>text_charAt</code>, <code>text_getSubstring</code>, <code>text_changeCase</code>, <code>text_trim</code>, <code>text_count</code>, <code>text_replace</code>, <code>text_reverse</code></td><td>Enthalten; zusätzlich mehrzeiliger Text, Zeilenumbruch, enthält und Zahlenformatierung</td><td>Umgesetzt einschließlich Textumkehr. Teiltext hat derzeit Grenzen vom Anfang; weitere Positionsvarianten und ioBroker-Zahlenformatierung offen.</td></tr><tr><td>Text: <code>text_print</code>, <code>text_prompt</code>, <code>text_prompt_ext</code></td><td>Nicht angeboten</td><td>Ausgabe über HA-Log-Aktion. Browser-Prompt wäre keine spätere HA-Eingabe und wird nicht als solche eingebaut.</td></tr><tr><td>Listen: <code>lists_create_empty</code>, <code>lists_create_with</code>, <code>lists_repeat</code>, <code>lists_length</code>, <code>lists_isEmpty</code>, <code>lists_indexOf</code>, <code>lists_getIndex</code>, <code>lists_setIndex</code>, <code>lists_getSublist</code>, <code>lists_split</code>, <code>lists_sort</code>, <code>lists_reverse</code></td><td>Enthalten; leere Liste als Variante</td><td>Liste erstellen mit 0–100 Eingängen, Wiederholung, Suchen/Lesen/Setzen/Entfernen/Einfügen, Teilbereich, Teilen/Verbinden, Sortieren/Umkehren umgesetzt. Kombiniertes Lesen-und-Entfernen, weitere End-/Zufallspositionen offen.</td></tr><tr><td>Variablen: <code>variables_get</code>, <code>variables_set</code>, dynamische Typvarianten <code>variables_get_dynamic</code>, <code>variables_set_dynamic</code></td><td>Dynamische Kategorie VARIABLE, keine VARIABLE_DYNAMIC-Kategorie</td><td>Erstellen, Lesen, Setzen, Erhöhen umgesetzt. Typauswahl/typed-variable-modal bleibt vorgemerkt. Originaler Getter zusätzlich für Funktionsparameter.</td></tr><tr><td>Funktionen: <code>procedures_defreturn</code>, <code>procedures_callreturn</code>, <code>procedures_defnoreturn</code>, <code>procedures_callnoreturn</code>, <code>procedures_ifreturn</code></td><td>Dynamische Kategorie PROCEDURE</td><td>Neu: originale Wertdefinition/Aufruf mit Parametern und Rückgabewert. Aktionen ohne Rückgabewert über vorhandenen HA-Script-Aufruf; keine lokalen Aktionsfunktionen oder frühes return.</td></tr><tr><td>Farbe: picker/random/rgb/blend aus field-colour</td><td>Alle vier enthalten</td><td>Jetzt Farbwähler plus Zufall, RGB und Mischung in eigener Kategorie; eigene HA-Generatoren statt JavaScript.</td></tr></tbody></table><p>Interne Mutator-Hilfsblocks sind keine eigenständigen Anwenderblocks. Ältere Aliasformen werden über ihre entsprechende Funktion berücksichtigt. Bei ioBroker zusätzlich vorhandene Kategorien System, Aktionen, Sendto, Datum/Zeit, Konvertierung, Trigger, Timeouts und Objekt sind Erweiterungen der Script-Engine. Unsere bereits dokumentierten Gegenstücke stehen unter <a href="./time">Datum/Zeit</a>, <a href="./conversion">Konvertierung</a>, <a href="./flow">Timeouts/Objekt/Logik</a> und <a href="./collections">Sammlungen</a>. Fremde Adapter und nachinstallierte Drittplugins sind nicht Bestandteil dieses Standardvergleichs. Sendto/JSONata und benannte JavaScript-Timer werden nicht als native HA-Funktionen ausgegeben.</p><h2 id="farben-verwenden" tabindex="-1">Farben verwenden <a class="header-anchor" href="#farben-verwenden" aria-label="Permalink to &quot;Farben verwenden&quot;">​</a></h2><p>Unter <strong>Farbe</strong> stehen Farbauswahl, Zufallsfarbe, RGB-Prozentanteile und Mischung. Prozentwerte werden auf 0–100, der Mischanteil auf 0–1 begrenzt. Kanäle werden auf 0–255 umgerechnet und halbe positive Werte aufgerundet. Mischung 0 liefert Farbe 1, Mischung 1 Farbe 2; Rot/Blau mit 0,5 ergibt <code>[128, 0, 128]</code>. Keine Gamma-Korrektur.</p><p>Anders als die originalen JavaScript-Farbblocks liefern unsere berechneten Werte <strong>RGB-Listen für HA</strong>, keine Hextexte. Den Block an <strong>Licht → Farbe</strong> oder an eine Variablenzuweisung anschließen. Ein fester Farbwähler exportiert weiterhin eine native RGB-Liste; Berechnungen ein Template in <code>data.rgb_color</code>. Eine gespeicherte RGB-Variable kann ebenfalls angeschlossen werden. Es werden genau drei numerische Kanäle von 0–255 verlangt; Hextext zuerst bewusst umwandeln. Ungültige Werte führen zum Templatefehler.</p><p>Die Mischung wertet jeden direkt angeschlossenen Farbblock einmal aus. Veränderliche Zahlen-/Template-Eingänge, insbesondere der Mischanteil, vor Verwendung in einer Variablen speichern: generierte Typprüfungen oder mehrfach verwendete Funktionsparameter können Ausdrücke mehrfach auswerten. Zufall ist nicht kryptografisch. Die Generatoren nutzen die dokumentierten HA-Helfer <a href="https://www.home-assistant.io/template-functions/zip/" target="_blank" rel="noreferrer">zip</a>, <a href="https://www.home-assistant.io/template-functions/multiply/" target="_blank" rel="noreferrer">multiply</a> und <a href="https://www.home-assistant.io/template-functions/add/" target="_blank" rel="noreferrer">add</a>. Die Funktionsreferenz gilt für aktuelles HA; auf älteren Installationen Verfügbarkeit prüfen.</p><h2 id="wertfunktionen-verwenden" tabindex="-1">Wertfunktionen verwenden <a class="header-anchor" href="#wertfunktionen-verwenden" aria-label="Permalink to &quot;Wertfunktionen verwenden&quot;">​</a></h2><ol><li><strong>Funktionen</strong> öffnen und einen Definitionsblock auf die Arbeitsfläche ziehen.</li><li>Beispielsweise <code>doppelt</code> nennen; im originalen Zahnrad einen Parameter <code>x</code> hinzufügen.</li><li>Als Rückgabewert <strong>Variable x × Zahl 2</strong> anschließen. Parameter werden über Variablen-Getter gelesen.</li><li>Kategorie erneut öffnen: Der Aufruf <code>doppelt</code> mit Eingang <code>x</code> steht dynamisch bereit. Zahl 21 anschließen und den Aufruf beispielsweise einer Variablen zuweisen.</li></ol><p>Beim Export entsteht der entsprechende Jinja-Ausdruck mit dem Argument 21, keine JavaScript-/Python-Funktion. Bis zu acht unterschiedliche Parameter; Namen aus ASCII-Buchstaben, Ziffern und Unterstrich, beginnend mit Buchstabe oder Unterstrich. Verschachtelte Aufrufe sind innerhalb der allgemeinen Ausdruckstiefengrenze möglich. Rekursion, fehlende Argumente/Rückgabewerte, doppelte Namen und Aktionskörper verhindern den Export. Innerhalb einer Wertfunktion haben Parameter Vorrang vor gleichnamigen Automationsvariablen. Außerhalb gelten normale HA-Variablen und deren Gültigkeit. Rückgabewerte werden zur Laufzeit nicht allein durch die Blockly-Anschlussfarbe typisiert; in Bedingungen muss das Ergebnis Boolean sein.</p><p>JSON-Projekte erhalten Definitionen, Parameter und Aufrufe. YAML speichert die expandierte Bedeutung und öffnet diese später als Template; daraus werden keine Funktionsdefinitionen rekonstruiert. Der vorgemerkte Developer-Tools-Import für freie Block-/Template-Pakete bleibt eine separate Roadmap-Aufgabe.</p><p>Verifiziert: Projekt-/YAML-Rundlauf, Farbgrenzen, Jinja-Auswertung mit immutable Sandbox und nachgebildeten HA-Helfern, originaler Funktionsmutator, dynamisches Menü und Browser-Neuladen. Eine Ausführung in einer echten Home-Assistant-Installation steht noch aus.</p><p><a href="./blocks">Blockbilder und Einzelbeschreibungen</a> · <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-colour" target="_blank" rel="noreferrer">Originales field-colour</a> · <a href="https://developers.google.com/blockly/guides/create-custom-blocks/overview" target="_blank" rel="noreferrer">Eigene Blockly-Blöcke</a></p>',23)])])}const b=n(a,[["render",o]]);export{g as __pageData,b as default};
